@csrf_exempt
def attach_payment_method(request):
    if request.method == "POST":
        try:
            # Parse the JSON data from the request body
            data = json.loads(request.body)

            # Ensure values are strings
            payment_method_id = str(data.get("paymentMethodId", ""))
            customer_id = str(data.get("customerId", ""))

            # Validate inputs
            if not payment_method_id or not customer_id:
                return JsonResponse({"success": False, "error": "Invalid payment method ID or customer ID"})

            # Attach the payment method to the customer
            payment_method = stripe.PaymentMethod.attach(
                payment_method_id,
                customer=customer_id
            )

            stripe.PaymentMethod.modify(
                payment_method_id,
                metadata={"allow_redisplay": "always"}
            )

            # Set the payment method as the default for invoices
            stripe.Customer.modify(
                customer_id,
                invoice_settings={"default_payment_method": payment_method_id},
            )

            # Return the success response with the attached payment method
            return JsonResponse({"success": True, "paymentMethod": payment_method})
        except Exception as e:
            # Handle and return any errors
            return JsonResponse({"success": False, "error": str(e)})

    # Handle invalid request methods
    return JsonResponse({"success": False, "error": "Invalid request method"})

@csrf_exempt
def create_customer(request):
    if request.method == "POST":
        try:
            data = json.loads(request.body)
            customer = stripe.Customer.create(
                email=data["email"]
            )
            return JsonResponse({"success": True, "customer": customer})
        except Exception as e:
            return JsonResponse({"success": False, "error": str(e)})
    return JsonResponse({"success": False, "error": "Invalid request method"})

@method_decorator(csrf_exempt, name='dispatch')
class CreateStripeCheckoutSession(APIView):
    def post(self, request, *args, **kwargs):
        bookingId = self.kwargs['pk']
        try:
            # Get the booking by ID
            booking = Booking.objects.get(id=bookingId)

            # Use the related manager to access tickets
            tickets = booking.tickets.all()

            childAmt = adultAmt = seniorAmt = 0

            # Calculate quantities for each ticket type
            for ticket in tickets:
                if ticket.type == "child":
                    childAmt += 1
                elif ticket.type == "adult":
                    adultAmt += 1
                elif ticket.type == "senior":
                    seniorAmt += 1

            # Prepare line items dynamically
            line_items = []
            if childAmt > 0:
                line_items.append({
                    'price_data': {
                        'currency': 'usd',
                        'unit_amount': 6 * 100,
                        'product_data': {'name': 'Child Ticket'},
                    },
                    'quantity': childAmt,
                })
            if adultAmt > 0:
                line_items.append({
                    'price_data': {
                        'currency': 'usd',
                        'unit_amount': 8 * 100,
                        'product_data': {'name': 'Adult Ticket'},
                    },
                    'quantity': adultAmt,
                })
            if seniorAmt > 0:
                line_items.append({
                    'price_data': {
                        'currency': 'usd',
                        'unit_amount': 7 * 100,
                        'product_data': {'name': 'Senior Ticket'},
                    },
                    'quantity': seniorAmt,
                })

            # Extract the stripe_id from the POST data
            stripe_id = request.data.get('stripe_id', None)

            if not stripe_id:
                return JsonResponse({'success': False, 'error': 'Stripe ID is required'})

            # Fetch the customer's saved payment methods
            payment_methods = stripe.PaymentMethod.list(
                customer=stripe_id,
                type="card",  # Only fetch saved card payment methods
            )

            # Create Stripe Checkout session with saved payment methods support
            checkout_session_data = {
                'line_items': line_items,
                'allow_promotion_codes': True,
                'automatic_tax': {'enabled': False},
                'mode': 'payment',
                'success_url': 'http://localhost:3000/bookings/?success=true',
                'cancel_url': 'http://localhost:3000/bookings/?canceled=true',
                'customer': stripe_id,
                'payment_method_types': ['card'],
                'payment_intent_data': {
                    'setup_future_usage': 'off_session',  # This will save the card for future use
                },
            }

            # Create the checkout session
            checkout_session = stripe.checkout.Session.create(**checkout_session_data)

            response = JsonResponse({'url': checkout_session.url, 'sessionid': checkout_session.id})
            response["Access-Control-Allow-Origin"] = "http://localhost:3000"
            response["Access-Control-Allow-Methods"] = "POST, GET, OPTIONS"
            response["Access-Control-Allow-Headers"] = "Content-Type"
            return response

        except Exception as e:
            response = JsonResponse({'msg': 'Error creating Stripe session', 'error': str(e)}, status=500)
            response["Access-Control-Allow-Origin"] = "http://localhost:3000"
            response["Access-Control-Allow-Methods"] = "POST, GET, OPTIONS"
            response["Access-Control-Allow-Headers"] = "Content-Type"
            return response


@csrf_exempt
def stripe_webhook_view(request):
    payload = request.body
    endpoint = settings.STRIPE_WEBHOOK_SECRET
    sig_header = request.META['HTTP_STRIPE_SIGNATURE']
    event = None
    try:
        event = stripe.Webhook.construct_event(
            payload, sig_header, endpoint
        )
    except ValueError as e:
        return HttpResponse(status=400)
    except stripe.error.SignatureVerificationError as e:
        return HttpResponse(status=400)

    if event['type'] == 'checkout.session.completed':
        session = event['data']['object']
        print(session)
        customer_email=session['customer_details']['email']
        prod_id=session['metadata']['product_id']
        product=Ticket.objects.get(id=prod_id)
        #sending confimation mail
        send_mail(
            subject="payment sucessful",
            message=f"thank for your purchase. your order is ready.",
            recipient_list=[customer_email],
            from_email=settings.DEFAULT_FROM_EMAIL
        )
        PaymentHistory.objects.create(product=product, payment_status=True)
    return HttpResponse(status=200)

